/**
 * Official Kunta Publications Imprint Logo Asset
 * High-resolution brand logo for Amazon KDP Covers, Interior Pages & Studio
 */

export const KUNTA_LOGO_PNG_PATH = '/assets/kunta-publications-logo.png';
export const KUNTA_LOGO_FALLBACK_PATH = '/kunta-publications-logo.png';

export const KUNTA_LOGO_BASE64 = 'data:image/png;base64,';

export const KUNTA_LOGO_ASPECT_RATIO = 387 / 103; // ~3.757

/**
 * Renders an embedded SVG image element for the official Kunta Publications logo
 */
export function renderKuntaLogoSvg(x: number, y: number, width: number, height: number, opacity: number = 1): string {
  return `
    <g class="kunta-publisher-logo">
      <image 
        href="${KUNTA_LOGO_BASE64}" 
        x="${x}" 
        y="${y}" 
        width="${width}" 
        height="${height}" 
        preserveAspectRatio="xMidYMid meet"
        opacity="${opacity}"
      />
    </g>
  `;
}

/**
 * Renders a stylized badge containing the Kunta Publications logo
 */
export function renderKuntaLogoBadgeSvg(x: number, y: number, width: number, height: number): string {
  return `
    <g class="kunta-publisher-badge" transform="translate(${x}, ${y})">
      <rect 
        x="0" 
        y="0" 
        width="${width}" 
        height="${height}" 
        rx="8" 
        fill="#0b192c" 
        stroke="#ffffff" 
        stroke-width="1.5" 
        stroke-opacity="0.4"
      />
      <image 
        href="${KUNTA_LOGO_BASE64}" 
        x="4" 
        y="2" 
        width="${width - 8}" 
        height="${height - 4}" 
        preserveAspectRatio="xMidYMid meet"
      />
    </g>
  `;
}
